import { DiGraph } from 'digraph-js';
import type { DAGData, DAGNode, DAGEdge } from './simple-dag-generator';

export class DAG {
  private digraph: DiGraph<any>;
  
  constructor(dagData: DAGData) {
    this.digraph = this.convertToDiGraph(dagData);
  }
  
  /**
   * Get the maximum depth of the DAG (0-indexed)
   */
  getDepth(): number {
    // For DAGs generated by our generator, use structural depth based on node IDs
    const vertices = this.digraph.toDict();
    let maxLevel = 0;
    
    for (const nodeId of Object.keys(vertices)) {
      const match = nodeId.match(/node-(\d+)-\d+/);
      if (match) {
        const level = parseInt(match[1]);
        maxLevel = Math.max(maxLevel, level);
      }
    }
    
    // Return depth (levels are 0-indexed, so depth = maxLevel + 1)
    return maxLevel + 1;
  }
  
  /**
   * Get the maximum width (number of nodes) at any layer
   */
  getWidth(): number {
    // For DAGs generated by our generator, use structural width based on node IDs
    const vertices = this.digraph.toDict();
    const levelCounts = new Map<number, number>();
    
    for (const nodeId of Object.keys(vertices)) {
      const match = nodeId.match(/node-(\d+)-\d+/);
      if (match) {
        const level = parseInt(match[1]);
        levelCounts.set(level, (levelCounts.get(level) || 0) + 1);
      }
    }
    
    // Return maximum width across all levels
    let maxWidth = 0;
    for (const count of levelCounts.values()) {
      maxWidth = Math.max(maxWidth, count);
    }
    return maxWidth;
  }
  
  /**
   * Get all nodes grouped by their depth level
   */
  getLayers(): Map<number, string[]> {
    const layers = new Map<number, string[]>();
    
    // Find source nodes (nodes with no parents) - these are at depth 0
    const vertices = this.digraph.toDict();
    const sourceNodes: string[] = [];
    for (const [nodeId, vertex] of Object.entries(vertices)) {
      const parents = this.digraph.getParents(nodeId);
      if (parents.length === 0) {
        sourceNodes.push(nodeId);
      }
    }
    
    // Initialize layer 0 with source nodes
    layers.set(0, sourceNodes);
    
    // Use digraph-js traverseEager with DFS to get all nodes in depth order
    const allNodes = this.digraph.traverseEager({ traversal: "dfs" });
    const nodeDepths = new Map<string, number>();
    
    // Start with source nodes at depth 0
    sourceNodes.forEach(nodeId => {
      nodeDepths.set(nodeId, 0);
    });
    
    // For each node, compute its depth based on its parents
    for (const vertex of allNodes) {
      if (!sourceNodes.includes(vertex.id)) {
        const parents = this.digraph.getParents(vertex.id);
        if (parents.length > 0) {
          // Node's depth = max(parent depths) + 1
          const parentDepths = parents.map(parent => nodeDepths.get(parent.id) || 0);
          const depth = Math.max(...parentDepths) + 1;
          nodeDepths.set(vertex.id, depth);
          
          // Add to layers
          if (!layers.has(depth)) {
            layers.set(depth, []);
          }
          layers.get(depth)!.push(vertex.id);
        }
      }
    }
    
    return layers;
  }
  
  /**
   * Get the depth of a specific node
   */
  getNodeDepth(nodeId: string): number {
    // For DAGs generated by our generator, use structural depth based on node ID
    const match = nodeId.match(/node-(\d+)-\d+/);
    if (match) {
      return parseInt(match[1]);
    }
    return -1; // Node not found or doesn't match expected pattern
  }
  
  /**
   * Get all nodes at a specific depth
   */
  getNodesAtDepth(depth: number): string[] {
    const layers = this.getLayers();
    return layers.get(depth) || [];
  }
  
  /**
   * Check if the DAG has cycles
   */
  hasCycles(): boolean {
    return this.digraph.hasCycles();
  }
  
  /**
   * Get the underlying digraph for advanced operations
   */
  getDigraph(): DiGraph<any> {
    return this.digraph;
  }
  
  private convertToDiGraph(dagData: DAGData): DiGraph<any> {
    const digraph = new DiGraph();
    
    // Add all nodes
    dagData.nodes.forEach(node => {
      digraph.addVertex({
        id: node.id,
        adjacentTo: [],
        body: { label: node.label, type: node.type }
      });
    });
    
    // Add all edges
    dagData.edges.forEach(edge => {
      digraph.addEdge({ from: edge.source, to: edge.target });
    });
    
    return digraph;
  }
} 